// Port of JS8Core/Tests/JS8CoreTests/DecoderComparisonTests.swift.
package com.js8firefly.core

import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Assume
import org.junit.Before
import org.junit.Test
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min
import kotlin.math.truncate

/**
 * Audio-level cross-checks: signals generated by the reference are decoded
 * by both decoders, and signals generated by the Kotlin modulator are decoded
 * by the reference decoder.
 */
class DecoderComparisonTests {
    private lateinit var ref: RefHarness
    private val dir = File(System.getProperty("java.io.tmpdir"), "js8tests")

    @Before
    fun setUp() {
        Assume.assumeTrue("reference harness not built", RefHarness.isAvailable)
        ref = RefHarness()
        dir.mkdirs()
    }

    @After
    fun tearDown() {
        if (::ref.isInitialized) ref.close()
    }

    /** Swift `Int.random(in: 0..<upper, using: &g)` (Lemire's method, as in the Swift stdlib). */
    private fun randomInt(g: SeededGenerator, upper: Int): Int {
        val u = upper.toLong()
        fun mulHigh(a: Long, b: Long): Long = Math.multiplyHigh(a, b) + ((a shr 63) and b) + ((b shr 63) and a)
        var random = g.next()
        var low = random * u
        if (java.lang.Long.compareUnsigned(low, u) < 0) {
            val t = java.lang.Long.remainderUnsigned(-u, u)
            while (java.lang.Long.compareUnsigned(low, t) < 0) {
                random = g.next()
                low = random * u
            }
        }
        return mulHigh(random, u).toInt()
    }

    private fun randomFrame(g: SeededGenerator): String =
        String(CharArray(12) { JS8Codec.alphabet[randomInt(g, 64)] })

    private fun readRaw(file: File): FloatArray {
        val bb = ByteBuffer.wrap(file.readBytes()).order(ByteOrder.LITTLE_ENDIAN)
        return FloatArray(bb.remaining() / 2) { bb.short.toFloat() }
    }

    private fun swiftRounded(x: Float): Float {
        val t = truncate(x)
        return if (abs(x - t) >= 0.5f) t + (if (x < 0) -1f else 1f) else t
    }

    private fun writeRaw(samples: FloatArray, file: File) {
        val bb = ByteBuffer.allocate(samples.size * 2).order(ByteOrder.LITTLE_ENDIAN)
        for (v in samples) bb.putShort(max(-32767f, min(32767f, swiftRounded(v))).toInt().toShort())
        file.writeBytes(bb.array())
    }

    data class Line(val frame: String, val type: Int, val snr: Int, val dt: Float, val freq: Float)

    private fun parse(lines: List<String>): List<Line> = lines.map { l ->
        val f = l.split("\t")
        Line(frame = f[0], type = f[1].toInt(), snr = f[2].toInt(), dt = f[3].toFloat(), freq = f[4].toFloat())
    }

    private fun swiftDecode(samples: FloatArray, submode: JS8Submode, nfqso: Int = 1500): List<Line> {
        val dec = JS8ModeDecoder(submode)
        val out = ArrayList<Line>()
        dec.decode(samples = samples, nfqso = nfqso) { d ->
            out.add(Line(frame = d.frame, type = d.type, snr = d.snr, dt = d.dt, freq = d.frequency))
        }
        return out
    }

    @Test
    fun testReferenceSignalsDecodeIdentically() {
        val g = SeededGenerator(11)
        var total = 0
        var refOK = 0
        var swiftOK = 0
        val snrDiffs = ArrayList<Int>()
        for (submode in JS8Submode.allCases) {
            for (snr in listOf(-10, -16, -20, -24)) {
                for (k in 0 until 3) {
                    val frame = randomFrame(g)
                    val type = randomInt(g, 8)
                    val freq = 500 + randomInt(g, 2000).toDouble()
                    val file = File(dir, "ref_${submode.rawValue}_${snr}_$k.raw")
                    assertEquals(
                        "OK",
                        ref.call(listOf("GEN", file.path, "${submode.rawValue}", "$freq", "$type", frame, "$snr", "${k + 1}")),
                    )
                    val refLines = parse(ref.callUntilEnd(listOf("DECODE", file.path, "${submode.rawValue}", "1500")))
                    val swiftLines = swiftDecode(readRaw(file), submode)
                    total += 1
                    val r = refLines.firstOrNull { it.frame == frame && it.type == type }
                    val s = swiftLines.firstOrNull { it.frame == frame && it.type == type }
                    if (r != null) refOK += 1
                    if (s != null) swiftOK += 1
                    if (r != null && s != null) {
                        snrDiffs.add(abs(r.snr - s.snr))
                        assertEquals("freq $submode $snr", r.freq, s.freq, 0.6f)
                        assertEquals("dt $submode $snr", r.dt, s.dt, 0.02f)
                    }
                    if ((r == null) != (s == null)) {
                        println("MISMATCH $submode snr $snr ref=${r != null} kotlin=${s != null}")
                    }
                    // Never decode garbage.
                    assertTrue("false decode $swiftLines", swiftLines.all { it.frame == frame })
                }
            }
        }
        println("decodes: total=$total reference=$refOK kotlin=$swiftOK maxSNRdiff=${snrDiffs.maxOrNull() ?: -1}")
        assertTrue("kotlin $swiftOK < reference $refOK", swiftOK >= refOK)
        assertTrue("max SNR diff ${snrDiffs.maxOrNull()}", (snrDiffs.maxOrNull() ?: 0) <= 1)
    }

    @Test
    fun testSwiftModulatedSignalsDecodeInReference() {
        val g = SeededGenerator(21)
        for (submode in JS8Submode.allCases) {
            for (k in 0 until 4) {
                val frame = randomFrame(g)
                val type = randomInt(g, 8)
                val freq = 400 + randomInt(g, 2200).toDouble()
                val tones = JS8Codec.encode(type = type, frame = frame, costas = submode.costas)!!
                val wave = JS8Modulator.synthesize(tones = tones, frequency = freq, submode = submode, sampleRate = 12000.0, amplitude = 1f)
                val samples = FloatArray(submode.samplesPerPeriod)
                val start = submode.startDelayMS * 12
                val noise = SeededGenerator((k + 100).toLong())
                for (i in samples.indices) {
                    val s: Float = if (i >= start && i - start < wave.size) wave[i - start] else 0f
                    samples[i] = 1000 * s + 600 * gaussian(noise)
                }
                val file = File(dir, "swift_${submode.rawValue}_$k.raw")
                writeRaw(samples, file)
                val refLines = parse(ref.callUntilEnd(listOf("DECODE", file.path, "${submode.rawValue}", "1500")))
                assertTrue(
                    "reference failed to decode Kotlin signal $submode $frame @ $freq: $refLines",
                    refLines.any { it.frame == frame && it.type == type },
                )
                val swiftLines = swiftDecode(samples, submode)
                assertTrue("kotlin failed $submode $frame", swiftLines.any { it.frame == frame && it.type == type })
            }
        }
    }

    @Test
    fun testMultipleSignalsAndTiming() {
        val submode = JS8Submode.normal
        val samples = FloatArray(submode.samplesPerPeriod)
        val noise = SeededGenerator(5)
        val frames = listOf("HELLOWORLD12", "KN4CRDTESTAB", "abcdefghijkl", "0123456789-+")
        val freqs = listOf(600.0, 1100.0, 1520.0, 2200.0)
        val offsets = listOf(0.0, 0.3, -0.2, 0.8)
        for ((i, f) in frames.withIndex()) {
            val tones = JS8Codec.encode(type = i, frame = f, costas = submode.costas)!!
            val wave = JS8Modulator.synthesize(tones = tones, frequency = freqs[i], submode = submode, sampleRate = 12000.0)
            val start = submode.startDelayMS * 12 + (offsets[i] * 12000).toInt()
            for ((j, v) in wave.withIndex()) {
                if (start + j >= 0 && start + j < samples.size) samples[start + j] += 300 * v
            }
        }
        for (i in samples.indices) samples[i] += 500 * gaussian(noise)
        val t0 = System.nanoTime()
        val lines = swiftDecode(samples, submode)
        println("multi-signal decode took ${(System.nanoTime() - t0) / 1e9} s: $lines")
        for ((i, f) in frames.withIndex()) {
            val l = lines.firstOrNull { it.frame == f }
            if (l == null) {
                fail("missing $f")
                continue
            }
            assertEquals(freqs[i], l.freq.toDouble(), 1.0)
            assertEquals(offsets[i], l.dt.toDouble(), 0.05)
        }
        val file = File(dir, "multi.raw")
        writeRaw(samples, file)
        val refLines = parse(ref.callUntilEnd(listOf("DECODE", file.path, "0", "1500")))
        assertEquals(refLines.map { it.frame }.toSet(), lines.map { it.frame }.toSet())
    }
}
